<script setup lang="ts">
import type { components } from '~/api/schema';import {unwrap,versionHeaders} from '~/api/client';import {displayError} from '~/utils/errors';
type Row={product:string;sku:components['schemas']['Sku'];inventory:components['schemas']['Inventory'];delta:number;reason:string};definePageMeta({middleware:'auth'});const api=useMarketplaceApi();const portal=usePortal();const rows=ref<Row[]>([]);const pending=ref(true);const error=ref<unknown>();
async function load(){pending.value=true;error.value=undefined;try{if(!portal.activeStore.value)await portal.loadStores();if(!portal.storeId.value)return;const products=unwrap(await api.GET('/vendor/stores/{storeId}/products',{params:{path:{storeId:portal.storeId.value},query:{limit:100}},cache:'no-store'})).items;rows.value=await Promise.all(products.flatMap(product=>product.skus.map(async sku=>({product:product.name,sku,inventory:unwrap(await api.GET('/vendor/stores/{storeId}/skus/{skuId}/inventory',{params:{path:{storeId:portal.storeId.value,skuId:sku.id}},cache:'no-store'})),delta:0,reason:''}))));}catch(cause){error.value=cause;}finally{pending.value=false;}}
async function adjust(row:Row){if(!Number.isInteger(row.delta)||row.delta===0||row.reason.trim().length<3)return;try{row.inventory=unwrap(await api.POST('/vendor/stores/{storeId}/skus/{skuId}/stock-adjustments',{params:{path:{storeId:portal.storeId.value,skuId:row.sku.id},header:{...versionHeaders(row.inventory.row_version),'Idempotency-Key':crypto.randomUUID()}},body:{on_hand_delta:row.delta,reason:row.reason}}));row.delta=0;row.reason='';}catch(cause){error.value=cause;}}
watch(()=>portal.storeId.value,()=>{void load();});onMounted(()=>{void load();});useSeoMeta({title:'Persediaan — Niaga'});
</script>
<template><main id="main-content" class="page-shell"><PortalNav area="vendor"/><div class="section-heading"><div><p class="eyebrow">Stok</p><h1>Persediaan</h1></div><StoreSwitcher/></div><ApiState :pending="pending" :error="error?displayError(error):null" :empty="!pending&&!rows.length" empty-title="Belum ada SKU" @retry="load"><div class="inventory-grid"><article v-for="row in rows" :key="row.sku.id" class="surface"><div class="section-heading"><div><h2>{{ row.product }}</h2><small>{{ row.sku.sku_code }}</small></div><span class="badge">{{ row.sku.status }}</span></div><div class="metric-grid compact"><div><strong>{{ row.inventory.on_hand }}</strong><span>On hand</span></div><div><strong>{{ row.inventory.reserved }}</strong><span>Reserved</span></div><div><strong>{{ row.inventory.available }}</strong><span>Available</span></div></div><form class="inline-adjust" @submit.prevent="adjust(row)"><label>Perubahan<input v-model.number="row.delta" type="number" step="1" required></label><label>Alasan<input v-model.trim="row.reason" minlength="3" required></label><button :disabled="!row.delta||row.reason.length<3">Simpan</button></form></article></div></ApiState></main></template>
